import Autobase from 'autobase'
import Corestore from 'corestore'
const store = new Corestore('./data')
const base = new Autobase(store, null, {
  valueEncoding: 'json',
  open (store) { return store.get({ name: 'view', valueEncoding: 'json' }) },
  async apply (nodes, view) {
    for (const node of nodes) {
      if (node.value !== null) await view.append(node.value)
    }
  },
  async close (view) { await view.close() }
})
try {
  await base.ready()
  await base.append({ text: 'Hello ordered view' })
  await base.update()
  console.log((await base.view.get(base.view.length - 1)).text)
} finally {
  await base.close()
  await store.close()
}

import Autobee from 'autobee'
import Corestore from 'corestore'
const store = new Corestore('./data')
const db = new Autobee(store, null, {
  async apply (nodes, view) {
    const batch = view.write()
    for (const node of nodes) {
      if (node.value === null) continue
      const op = JSON.parse(node.value.toString())
      batch.tryPut(Buffer.from(op.key), Buffer.from(op.text))
    }
    await batch.flush()
  }
})
try {
  await db.ready()
  await db.append(Buffer.from(JSON.stringify({ key: 'welcome', text: 'Hello merged view' })))
  await db.update()
  console.log((await db.view.get(Buffer.from('welcome'))).value.toString())
} finally {
  await db.close()
  await store.close()
}

