import DHT from 'hyperdht'
// An isolated local bootstrap: this example never joins the public DHT.
const seed = DHT.bootstrapper(49777, '127.0.0.1')
await seed.ready()
const bootstrap = [{ host: '127.0.0.1', port: seed.address().port }]
const host = new DHT({ bootstrap })
const client = new DHT({ bootstrap })
const server = host.createServer(socket => {
  socket.on('error', () => {})
  socket.end('Hello encrypted peer')
})
let socket
let timer
try {
  await server.listen(DHT.keyPair())
  socket = client.connect(server.publicKey)
  const message = await new Promise((resolve, reject) => {
    timer = setTimeout(() => reject(new Error('Connection timed out')), 10000)
    let text = ''
    socket.on('data', chunk => { text += chunk.toString() })
    socket.on('end', () => resolve(text))
    socket.on('error', reject)
  })
  console.log(message)
} finally {
  clearTimeout(timer)
  socket?.destroy()
  await server.close()
  await Promise.all([host.destroy(), client.destroy()])
  await seed.destroy()
}

import Hyperswarm from 'hyperswarm'
import DHT from 'hyperdht'
import { randomBytes } from 'node:crypto'
const seed = DHT.bootstrapper(49777, '127.0.0.1')
await seed.ready()
const bootstrap = [{ host: '127.0.0.1', port: seed.address().port }]
const host = new Hyperswarm({ bootstrap })
const client = new Hyperswarm({ bootstrap })
const topic = randomBytes(32)
let timer
try {
  host.on('connection', socket => {
    socket.on('error', () => {})
    socket.end('Hello topic')
  })
  const received = new Promise((resolve, reject) => {
    timer = setTimeout(() => reject(new Error('Discovery timed out')), 10000)
    client.on('connection', socket => {
      let text = ''
      socket.on('data', chunk => { text += chunk.toString() })
      socket.on('end', () => resolve(text))
      socket.on('error', reject)
    })
  })
  // Start discovery and await the message together so failures are observed.
  const discovery = (async () => {
    await host.join(topic, { server: true, client: false }).flushed()
    client.join(topic, { server: false, client: true })
  })()
  const [message] = await Promise.all([received, discovery])
  console.log(message)
} finally {
  clearTimeout(timer)
  await Promise.all([host.destroy(), client.destroy()])
  await seed.destroy()
}

